import java.util.*;

public class Ex10CollectionsUtils {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(3, 1, 4, 1, 5, 9, 2));
        Collections.sort(list);
        System.out.println("sorted=" + list);
        System.out.println("binarySearch 4 idx=" + Collections.binarySearch(list, 4));
        System.out.println("frequency of 1=" + Collections.frequency(list, 1));
        List<Integer> unmod = Collections.unmodifiableList(list);
        try {
            unmod.add(0);
            System.out.println("added");
        } catch (UnsupportedOperationException e) {
            System.out.println("caught " + e.getClass().getSimpleName());
        }
    }
}
